'use strict';
(function(){
 const state=document.getElementById('state'),note=document.getElementById('state-note'),panel=document.getElementById('state-resources'),heading=document.getElementById('state-heading'),intro=document.getElementById('state-intro'),draft=document.getElementById('request-template'),download=document.getElementById('download-template'),print=document.getElementById('print-template');
 if(!state||!note||!panel||!heading||!intro||!draft||!download||!print)return;
 const rcfp='https://www.rcfp.org/open-government-guide/';
 const guideLink=document.getElementById('guide-link');
 // Preliminary official-source research only. Not an attorney-reviewed legal verification.
 const enhancedReviewStates=new Set(['Alabama','Alaska','Arizona','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming']);
 const verified={Utah:{law:'Utah Government Records Access and Management Act (GRAMA), Utah Code Title 63G, Chapter 2',summary:'ELIGIBILITY/SUBMISSION: Anyone may request qualifying public records from the governmental entity holding them; identify records specifically and keep a copy of the request. RESPONSE: GRAMA establishes response deadlines and separate expedited processing and extraordinary-circumstance rules; confirm the current applicable period in § 63G-2-204 rather than assuming all requests have the same deadline. FEES/EXEMPTIONS: Classification, privacy, protected records and allowable charges affect access. REVIEW: Start with the entity chief administrative officer; further appeals may go to the Government Records Office director or district court, depending on the statutory path. The 2026 § 63G-2-403 version generally gives 30 days to appeal the decision to the director, subject to specific exceptions and mediation tolling.',links:[['Utah Archives — GRAMA request and appeal FAQ','https://archives.utah.gov/transparency-services/government-records-access/faq/'],['Utah Legislature — 2026 appeal statute','https://le.utah.gov/xcode/title63g/chapter2/C63G-2-S403_2026050620260506.pdf']]},Vermont:{law:'Vermont Public Records Act, 1 V.S.A. §§ 315–320',summary:'ELIGIBILITY/SUBMISSION: A person may request qualifying public records from the agency custodian; identify the records sought. RESPONSE: Under § 318, promptly generally means immediately and no more than three business days, subject to statutory exceptions including unusual circumstances and storage. FEES/EXEMPTIONS: Agency copying/search fees and statutory exemptions apply; segregable nonexempt material must generally be released with appropriate redactions. REVIEW: Denials may be appealed to the agency head, who generally must decide within five business days; § 319 provides judicial review. Preserve denial notices and confirm the current procedure.',links:[['Vermont Legislature — § 318 procedure and appeals','https://legislature.vermont.gov/statutes/section/01/005/00318'],['Vermont Legislature — Public Records Act chapter','https://legislature.vermont.gov/statutes/fullchapter/01/005']]},Virginia:{law:'Virginia Freedom of Information Act, Va. Code § 2.2-3700 et seq.',summary:'ELIGIBILITY: Access is generally available to Virginia citizens and qualifying media representatives; agencies may require a requester name and legal address. RESPONSE: § 2.2-3704 generally requires a response within five working days; an appropriate written notice may extend the period by seven working days. Criminal-investigative-file requests under § 2.2-3706.1 may have a different 60-working-day extension. FEES/EXEMPTIONS: Actual-cost charges and exemptions for personnel, law-enforcement and other records may apply. REVIEW: Enforcement can involve court proceedings under § 2.2-3713; verify remedies and deadlines before filing.',links:[['Virginia Legislature — § 2.2-3704 current text','https://law.lis.virginia.gov/vacode/title2.2/chapter37/section2.2-3704/'],['Virginia FOIA Advisory Council — 2026 public records guide','https://foiacouncil.dls.virginia.gov/ref/Access%20to%20Public%20Records%202026%20DOCUMENT.html']]},Washington:{law:'Washington Public Records Act, RCW Chapter 42.56',summary:'ELIGIBILITY/SUBMISSION: Anyone may request identifiable, nonexempt public records from the appropriate agency. RESPONSE: RCW 42.56.520 requires an initial response within five business days, which may provide records, a link, an estimated timeframe, a clarification request, or a denial; it is not a universal five-day production deadline. FEES/EXEMPTIONS: Copying fees, personal privacy, personnel and investigative exemptions may apply. REVIEW: Denials require written reasons; judicial review under RCW 42.56.550 has a one-year filing provision measured from the agency claim of exemption or last installment production. Verify accrual and other procedural rules for a particular dispute.',links:[['Washington Legislature — response requirements','https://app.leg.wa.gov/Rcw/default.aspx?cite=42.56.520'],['Washington Legislature — judicial review','https://app.leg.wa.gov/RCW/default.aspx?Cite=42.56.550'],['Washington Legislature — full public records chapter','https://app.leg.wa.gov/RCW/default.aspx?cite=42.56&full=true']]},'West Virginia':{law:'West Virginia Freedom of Information Act, W. Va. Code § 29B-1-1 et seq.',summary:'ELIGIBILITY/SUBMISSION: Every person may request qualifying public records directly from the custodian; describe the records with reasonable specificity. RESPONSE: § 29B-1-3 generally requires the custodian, as soon as practicable and within five days excluding weekends and legal holidays, to furnish copies, offer inspection, or deny in writing with reasons. FEES/EXEMPTIONS: Actual reproduction costs may be charged, but search/retrieval labor charges are barred under § 29B-1-3(e); statutory privacy and other exemptions apply. REVIEW: A denial may be challenged for injunctive or declaratory relief in circuit court in the county where records are kept. Preserve the denial and seek advice about timing.',links:[['West Virginia Legislature — § 29B-1-3','https://code.wvlegislature.gov/29B-1-3/'],['West Virginia Legislature — full FOIA chapter','https://code.wvlegislature.gov/pdf/29B-1/']]},Wisconsin:{law:'Wisconsin Public Records Law, Wis. Stat. §§ 19.31–19.39',summary:'ELIGIBILITY/SUBMISSION: Any requester may ask the records authority for identifiable records; no special form is generally required. RESPONSE: § 19.35(4)(a) requires a response as soon as practicable and without delay, NOT a fixed number of days. FEES/EXEMPTIONS: Actual permissible copying charges apply; locating fees generally require at least $50 in location costs and advance payment may be required for charges above $5. Wisconsin also applies statutory exceptions and a public-interest balancing test. REVIEW: A requester can seek mandamus in court or ask the district attorney or Attorney General to pursue enforcement under § 19.37; those offices are not required to take every case.',links:[['Wisconsin DOJ — public records FAQ and enforcement','https://www.wisdoj.gov/Pages/AboutUs/public-records.aspx'],['Wisconsin DOJ — compliance guide','https://www.wisdoj.gov/Open%20Government/PRL_guide.pdf']]},Wyoming:{law:'Wyoming Public Records Act, Wyo. Stat. §§ 16-4-201–205',summary:'ELIGIBILITY/SUBMISSION: Any person may request public records from the designated public-records person of the governmental entity holding them. RESPONSE: § 16-4-202 provides for immediate release of readily available records when practicable; certain notices must be sent within seven business days; generally records must be released within 30 calendar days unless good cause prevents it. FEES/EXEMPTIONS: Reasonable electronic production costs, security and confidential-record exceptions may apply. REVIEW: The Governor’s Public Records Ombudsman can mediate and address certain disputes but does not give binding legal advice; district court remedies also exist. Confirm current law and any good-cause extension before taking action.',links:[['Wyoming Governor — Public Records Ombudsman','https://governor.wyo.gov/contact/public-records-ombudsman'],['Wyoming RCFP — statute and enforcement overview','https://www.rcfp.org/open-government-guide/wyoming/']]},'South Dakota':{law:'South Dakota Codified Laws Chapter 1-27, especially §§ 1-27-1 and 1-27-35–43',summary:'ELIGIBILITY: South Dakota residents and other persons interested in examining public records may inspect qualifying records. SUBMISSION: An informal request can be made to the custodian; after denial, submit a written request to the public record officer. RESPONSE: For that formal written request, the officer must provide records, deny with reasons, or acknowledge and estimate additional time within ten business days; failure to respond can be a deemed denial. FEES/EXEMPTIONS: Reasonable specialized-service fees, privacy, criminal investigation and other statutory exemptions apply; estimates may be required. REVIEW: A requester may generally initiate a civil action or Office of Hearing Examiners review within 90 days of denial. Confirm exact timing and filing procedures before acting.',links:[['South Dakota Legislature — Chapter 1-27','https://www.sdlegislature.gov/Statutes/1-27'],['South Dakota Attorney General — public records and disputes','https://atg.sd.gov/legal/opengovernment/publicrecords.aspx']]},Tennessee:{law:'Tennessee Public Records Act, Tenn. Code Ann. §§ 10-7-501 et seq.',summary:'ELIGIBILITY: The Act generally grants access to Tennessee citizens; agency policies and statutory exceptions affect eligibility and proof of citizenship. SUBMISSION: Contact the records custodian under the agency’s published policy; requests for inspection and copies may have different procedural requirements. RESPONSE: If prompt production is impracticable, the custodian must within seven business days provide the records, deny in writing with a basis, or give a written explanation of the time reasonably needed. FEES/EXEMPTIONS: Inspection generally is free; copies may incur permitted copying and labor charges, and confidential records remain protected. REVIEW: Denials may be challenged by petition in circuit or chancery court under § 10-7-505; seek advice promptly about deadlines.',links:[['Tennessee Comptroller — Public Records Act FAQ','https://comptroller.tn.gov/office-functions/open-records-counsel/open-meetings/frequently-asked-questions/tennessee-public-records-act-faqs.html'],['Tennessee Department of General Services — request procedures','https://www.tn.gov/generalservices/about-dgs/public-records-requests.html']]},Texas:{law:'Texas Public Information Act, Tex. Gov’t Code Chapter 552',summary:'ELIGIBILITY: Any person may request qualifying public information from a governmental body; written requests are important to trigger statutory procedures. SUBMISSION: Direct the request to the governmental body using an accepted method and sufficiently identify existing records. RESPONSE: Records must be produced promptly; ten business days is generally the deadline for an agency seeking to withhold records to request an Attorney General decision, NOT a universal production deadline. If production will exceed ten business days, the body generally must give a date. FEES/EXEMPTIONS: Statutory cost rules and confidentiality exceptions apply, including law-enforcement records. REVIEW: The Attorney General handles many withholding rulings and compliance complaints; court remedies may also exist. For a withholding ruling, agency submissions have additional 15-business-day requirements.',links:[['Texas Legislature — Government Code Chapter 552','https://tcss.legis.texas.gov/Docs/GV/htm/GV.552.htm'],['Texas Attorney General — Public Information Act overview','https://www.oag.state.tx.us/open-government/members-public/overview-public-information-act'],['Texas Attorney General — 2026 PIA Handbook','https://www.texasattorneygeneral.gov/sites/default/files/files/divisions/open-government/PIA-Handbook-2026.pdf']]},Oregon:{law:'Oregon Public Records Law, ORS 192.311–192.478',summary:'ELIGIBILITY: Any person may request nonexempt public records from the public body holding them; follow that body’s written request procedure. RESPONSE: ORS 192.324 generally requires acknowledgement or completion within five business days after a properly routed written request; ORS 192.329 requires completion as soon as practicable without unreasonable delay, subject to statutory exceptions. FEES/EXEMPTIONS: Actual-cost fees and potential public-interest waivers; criminal-investigation, privacy and attorney-client exemptions may apply. REVIEW: State-agency denials generally go to the Attorney General, local-body denials to the county district attorney, while denials by elected officials may require direct circuit-court action. Verify the specific appeal route before acting.',links:[['Oregon Legislature — ORS Chapter 192','https://www.oregonlegislature.gov/bills_laws/ors/ors192.html'],['Oregon DOJ — records law, fees and exemptions','https://www.doj.state.or.us/oregon-department-of-justice/public-records/public-records-and-meetings-law/'],['Oregon DOJ — denial appeals','https://www.doj.state.or.us/oregon-department-of-justice/public-records/appeal-a-state-agency-public-records-denial/']]},Pennsylvania:{law:'Pennsylvania Right-to-Know Law, 65 P.S. §§ 67.101–67.3104',summary:'ELIGIBILITY/SUBMISSION: Submit a sufficiently specific written request to the relevant Agency Open Records Officer; use the agency’s accepted submission method. RESPONSE: Normally five business days, with written interim extension allowed on statutory grounds; an extension beyond the permitted period may require requester agreement. FEES/EXEMPTIONS: Copying charges and exempt categories apply; some law-enforcement records follow distinct appeal rules. APPEAL: Many denials or deemed denials can be appealed to the Office of Open Records within 15 business days; exceptions apply to particular agencies and criminal-investigative records. Preserve the original request and denial.',links:[['Pennsylvania — official Right-to-Know instructions','https://www.pa.gov/services/ddap/file-a-right-to-know-request'],['Pennsylvania Office of Administration — response and appeals','https://www.pa.gov/agencies/oa/contact-us/right-to-know-law']]},'Rhode Island':{law:'Rhode Island Access to Public Records Act, R.I. Gen. Laws § 38-2-1 et seq.',summary:'ELIGIBILITY/SUBMISSION: Request reasonably identifiable nonexempt public records from the appropriate public body using its published APRA procedures. RESPONSE: Generally ten business days, with up to twenty additional business days for good cause. FEES/EXEMPTIONS: Copy and search charges and statutory exemptions may apply. APPEAL: A denial can be reviewed by the public body’s chief administrative officer, followed by a complaint to the Attorney General; Superior Court is another potential remedy. Verify the statute and applicable review deadlines before proceeding.',links:[['Rhode Island DHS — APRA response, fees and review','https://dhs.ri.gov/public-records'],['Rhode Island General Laws — Title 38, Chapter 2','https://webserver.rilegislature.gov/Statutes/TITLE38/38-2/INDEX.htm']]},'South Carolina':{law:'South Carolina Freedom of Information Act, S.C. Code §§ 30-4-10 et seq.',summary:'ELIGIBILITY/SUBMISSION: A person may make a written request to a public body for nonexempt records; some specified categories are available for in-person inspection without a written request. RESPONSE: The body generally must issue a determination within ten working days, or twenty working days if records are over 24 months old. If granted, production generally follows within 30 calendar days, or 35 for older records, with special deposit timing and written-extension rules. FEES/EXEMPTIONS: Reasonable fees, privacy, law-enforcement and personnel-related exemptions may apply. REVIEW: Statutory court enforcement provisions include eligibility and time-limit conditions; do not assume an administrative appeal.',links:[['South Carolina Legislature — FOIA Chapter 4','https://www.scstatehouse.gov/code/t30c004.php'],['South Carolina Legislature — archived statutory text for cross-check','https://www.scstatehouse.gov/Archives/CodeofLaws2024/t30c004']]},'New York':{law:'New York Freedom of Information Law (FOIL), Public Officers Law Article 6, §§ 84–90',summary:'FOIL covers records held by New York state and local government agencies, subject to exemptions. Send a reasonably described request to the agency holding the records. The New York Attorney General explains that agencies need not create records or provide legal research. Check agency acknowledgement, denial and appeal requirements in the current law. RESPONSE / PROCEDURAL CHECK: New York FOIL generally requires acknowledgment or response within five business days; appeal periods and acknowledgment estimates matter. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['New York Attorney General — make a FOIL request','https://ag.ny.gov/i-want/make-foil-request'],['New York Office of Mental Health — FOIL guidance','https://omh.ny.gov/omhweb/foil/index.html']]},'North Carolina':{law:'North Carolina Public Records Law, N.C. Gen. Stat. Chapter 132',summary:'Any person may inspect and obtain copies of qualifying public records. North Carolina generally requires copies as promptly as possible rather than imposing one universal numerical response deadline. Requests need no special form; actual copying costs and certain permitted service charges may apply. Agency-specific confidential-record exemptions still matter. RESPONSE / PROCEDURAL CHECK: North Carolina generally requires production as promptly as possible; there is no single universal numerical deadline. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['North Carolina Legislature — § 132-1','https://www.ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_132/GS_132-1.html'],['North Carolina Judicial Branch — public records FAQ','https://www.nccourts.gov/services/request-a-public-record/about-north-carolina-public-records-law'],['North Carolina DOJ — open government','https://ncdoj.gov/open-government/']]},'North Dakota':{law:'North Dakota Constitution Art. XI § 6; N.D.C.C. § 44-04-18 et seq.',summary:'Anyone, regardless of residency, may request reasonably identified public-entity records by phone, email, mail or in person; a written request is not generally required. A public entity must respond within a reasonable time, which varies with the request, and provide the legal basis for any denial. The Attorney General offers guidance and an open-records opinion process. RESPONSE / PROCEDURAL CHECK: North Dakota generally requires a response within a reasonable time; the Attorney General offers an open-records opinion process. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['North Dakota Attorney General — requesting records','https://attorneygeneral.nd.gov/open-records-meetings/requesting-public-records'],['North Dakota Attorney General — open records and meetings','https://attorneygeneral.nd.gov/open-records-meetings/'],['North Dakota Attorney General — 2026 manual','https://attorneygeneral.nd.gov/wp-content/uploads/2026/08/Open-Records-Manual-2026-1.pdf']]},Ohio:{law:'Ohio Public Records Act, Ohio Rev. Code § 149.43',summary:'Ohio generally allows any person to request public records without identifying themselves or explaining why, subject to specific statutory exceptions. Requests may be oral or written and must reasonably identify existing records. Records are to be made available promptly or within a reasonable period; consult the Attorney General Sunshine Laws Manual for exceptions and remedies. RESPONSE / PROCEDURAL CHECK: Ohio generally requires prompt inspection and copies within a reasonable time; Court of Claims and mandamus procedures differ. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Ohio Attorney General — Sunshine Laws Manual','https://www.ohioattorneygeneral.gov/Legal/Sunshine-Laws/The-Sunshine-Laws-Manual'],['Ohio Attorney General — 2026 Sunshine Manual','https://ohioattorneygeneral.gov/Files/Publications-Files/Publications-for-Legal/Sunshine-Laws-Publications/2025-Sunshine-Manual.aspx']]},Oklahoma:{law:'Oklahoma Open Records Act, 51 O.S. §§ 24A.1 et seq.',summary:'Oklahoma public-records requests are directed to the public body maintaining the records. The Oklahoma Attorney General publishes agency-specific procedures; its 2026 guidance requires use of its own request form for records held by that office, not necessarily other agencies. Exemptions, copying costs and reasonable access rules vary by record and custodian. RESPONSE / PROCEDURAL CHECK: Oklahoma generally requires prompt, reasonable access; there is no universal fixed numerical production deadline. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Oklahoma Attorney General — 2026 request instructions','https://oklahoma.gov/content/dam/ok/en/oag/open-records/2026.02.05%20-%20ORA%20Info%20Sheet%20and%20Form_Reader%20Extended.pdf']]},Nebraska:{law:'Nebraska Public Records Statutes, Neb. Rev. Stat. §§ 84-712–84-712.09',summary:'Nebraska allows public-records inspection or written requests to the government office holding records. Exemptions include certain medical, law-enforcement and security records. The Attorney General can review some denial disputes, and court relief may be available. RESPONSE / PROCEDURAL CHECK: Nebraska generally requires a response within four business days, with written explanations for delay. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Nebraska state public-records overview','https://statespending.nebraska.gov/PublicRecordsLaw'],['Nebraska Governor — request procedures','https://governor.nebraska.gov/public-records-request']]},Nevada:{law:'Nevada Public Records Act, NRS Chapter 239',summary:'Nevada law provides public-record access subject to exceptions. NRS 239.0107 generally requires agency action within five business days, which may include a written estimate rather than immediate production. NRS 239.011 provides a judicial remedy for qualifying denials, delays or fee disputes. RESPONSE / PROCEDURAL CHECK: Nevada generally requires a response within five business days; review § 239.0107 for available response options. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Nevada Legislature — Chapter 239','https://www.leg.state.nv.us/nrs/NRS-239.html'],['Nevada Department of Administration — requests','https://www.admin.nv.gov/public-records-requests/']]},'New Hampshire':{law:'New Hampshire Right-to-Know Law, RSA Chapter 91-A',summary:'New Hampshire RSA 91-A governs access to government records and meetings. Under RSA 91-A:4, if records are not immediately available, agencies generally must produce, deny or acknowledge with an estimated timeframe within five business days. Personnel and other exemptions may apply. RESPONSE / PROCEDURAL CHECK: New Hampshire generally requires access, denial, or written acknowledgment within five business days; verify the statute and case law. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['New Hampshire government — right-to-know guide','https://www.governor.nh.gov/sites/g/files/ehbemt336/files/documents/right-to-know-law-presentation.pdf'],['New Hampshire municipal statutory text and guidance','https://www.weare.nh.gov/town-administrator/files/request-for-public-materials-under-rsa-91-a-right-to-know-law']]},'New Jersey':{law:'New Jersey Open Public Records Act, N.J.S.A. 47:1A-1 et seq.',summary:'New Jersey OPRA governs access to government records, with exemptions and administrative denial-review procedures. The Government Records Council publishes guidance, request forms and complaint processes. Confirm current procedures following statutory amendments. RESPONSE / PROCEDURAL CHECK: New Jersey OPRA has important recent amendments; response periods, request forms, and Government Records Council procedures require current-law review. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['New Jersey Government Records Council','https://nj.gov/grc/'],['New Jersey Department of Community Affairs — OPRA','https://www.nj.gov/dca/home/opra.shtml']]},'New Mexico':{law:'New Mexico Inspection of Public Records Act, NMSA 1978 §§ 14-2-1–14-2-12',summary:'New Mexico IPRA generally allows oral or written requests, but statutory procedures and penalties apply to written requests. Official guidance identifies required requester contact details and a general 15-calendar-day inspection period, with intermediate notice requirements and exceptions. RESPONSE / PROCEDURAL CHECK: New Mexico IPRA generally has a 15-calendar-day inspection period and a three-business-day written acknowledgment rule. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['New Mexico Department of Justice — IPRA','https://nmag.gov/get-help/inspection-of-public-records-act/'],['New Mexico Secretary of State — IPRA','https://www.sos.nm.gov/legislation-and-lobbying/legal-resources/ipra-request-information/']]},Maine:{law:'Maine Freedom of Access Act, 1 M.R.S. §§ 400–414',summary:'Maine FOAA requests go directly to the agency holding the records. The state says no special form or written request is required, although written requests help preserve a record. The Public Access Ombudsman can mediate disputes; court remedies have separate requirements. RESPONSE / PROCEDURAL CHECK: Maine generally requires a written acknowledgment within five working days and a good-faith reasonable-time estimate. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Maine government — making a FOAA request','https://www.maine.gov/foaa/request/'],['Maine government — FOAA FAQ','https://www.maine.gov/foaa/faq/index.shtml'],['Maine Public Access Ombudsman','https://www.maine.gov/foaa/ombudsman/index.htm']]},Maryland:{law:'Maryland Public Information Act, Md. Code General Provisions §§ 4-101–4-601',summary:'Maryland PIA requests go to the custodian of the agency holding the records. Maryland distinguishes access by a person in interest from general public access in some situations. The independent Ombudsman helps mediate disputes, and some complaints may proceed to the PIA Compliance Board after attempted mediation. RESPONSE / PROCEDURAL CHECK: Maryland PIA generally requires production or denial within 30 days, with a ten-working-day notice if production will take longer. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Maryland Attorney General — Public Information Act','https://oag.maryland.gov/resources-info/Pages/public-information-act.aspx'],['Maryland Attorney General — October 2026 PIA Manual','https://oag.maryland.gov/resources-info/Pages/pia-manual.aspx'],['Maryland Attorney General — PIA FAQ','https://oag.maryland.gov/resources-info/Pages/public-information-act-faq.aspx']]},Mississippi:{law:'Mississippi Public Records Act, Miss. Code Ann. §§ 25-61-1 et seq.',summary:'The Mississippi Ethics Commission accepts public-records complaints, mediates disputes and can conduct hearings and issue orders. Its official site provides model rules, a link to the Act and a complaint form. Requesters should preserve any written denial. RESPONSE / PROCEDURAL CHECK: Mississippi generally requires production or denial within seven working days unless the requester and custodian agree otherwise. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Mississippi Ethics Commission — Public Records Act','https://www.ethics.ms.gov/publicrecords']]},Missouri:{law:'Missouri Sunshine Law, Mo. Rev. Stat. Chapter 610',summary:'Missouri public-records requests should be directed to the custodian of the public body that maintains the records. The Attorney General says no particular request format is required but recommends writing; the office also provides sample forms and a complaint process. RESPONSE / PROCEDURAL CHECK: Missouri Sunshine Law generally requires a response within three business days; more time may be reasonable with explanation. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Missouri Attorney General — Sunshine Law','https://ago.mo.gov/get-help/programs-services-from-a-z/sunshine-law/']]},Montana:{law:'Montana Constitution Art. II, §§ 9–10; Montana public-records statutes',summary:'Montana balances its constitutional right to know against individual privacy. The Office of Public Information Requests supports requests for participating state agencies; it does not necessarily cover every local public body. Verify the proper custodian and any privacy exemptions. RESPONSE / PROCEDURAL CHECK: Montana constitutional right-to-know law has specific response requirements under current Title 2, Chapter 6, Part 10; confirm exceptions. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Montana Office of Public Information Requests','https://montanaveba.mt.gov/OPIR/'],['Montana Secretary of State — privacy and right to know','https://sosmt.gov/records/privacy']]},Massachusetts:{law:'Massachusetts Public Records Law, M.G.L. c. 66, § 10 and c. 4, § 7(26)',summary:'Massachusetts uses designated Records Access Officers for public-record requests. The Secretary of the Commonwealth provides a guide and oversees public-record appeals. Exemptions and response obligations depend on the record and custodian. RESPONSE / PROCEDURAL CHECK: Massachusetts generally uses ten-business-day response requirements; agency and municipal appeals can involve the Supervisor of Records. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Massachusetts Secretary — public records resources','https://www.mass.gov/public-records-requests-for-the-secretary-of-the-commonwealth'],['Massachusetts Attorney General — request guidance','https://www.mass.gov/info-details/guidance-for-making-a-public-records-request']]},Michigan:{law:'Michigan Freedom of Information Act, 1976 PA 442, MCL 15.231–15.246',summary:'Michigan FOIA provides access to qualifying public-body records subject to statutory exemptions. Submit a written request to the public body’s FOIA coordinator. Under MCL 15.235, the public body generally must respond within five business days of legal receipt, and may issue one notice extending its response period by up to ten business days. An emailed request ordinarily is legally received one business day after transmission, subject to the statutory spam-folder rule. A response is not necessarily delivery of all requested records. Denial appeals and court review are governed by MCL 15.240, and fee challenges by MCL 15.240a. Preserve the request, receipt evidence, response and any extension notice. This is a public-records route, not a substitute for employee-specific discovery or personnel-access rights. RESPONSE / PROCEDURAL CHECK: Michigan FOIA generally requires a response within five business days, with a single statutory ten-business-day extension; appeals differ for denials and fees. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Michigan Legislature — full FOIA act','https://www.legislature.mi.gov/Laws/MCL?objectName=MCL-ACT-442-OF-1976'],['Michigan Legislature — request requirements','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-233'],['Michigan Legislature — response deadlines','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-235'],['Michigan Attorney General — FOIA FAQ','https://www.michigan.gov/ag/resources/foia'],['Michigan Legislature — appeals','https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-15-240']]},Minnesota:{law:'Minnesota Government Data Practices Act, Minn. Stat. Chapter 13',summary:'Minnesota generally treats government data as public unless classified otherwise by state or federal law. Agencies distinguish public-data requests from requests for data about oneself; data subjects may have different access rights. Fees and request methods vary by agency and type of access. RESPONSE / PROCEDURAL CHECK: Minnesota Data Practices Act generally requires a prompt response; data-subject requests have separate statutory timelines. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Minnesota Office of State Procurement — data requests','https://mn.gov/admin/osp/contact-us/data-requests/'],['Minnesota Department of Health — data practices','https://www.health.mn.gov/data/datapractices']]},Indiana:{law:'Indiana Access to Public Records Act, Ind. Code § 5-14-3',summary:'Indiana public agencies must respond to public-record requests under APRA, with response acknowledgement requirements that depend on delivery method. The Public Access Counselor handbook explains reasonable particularity, exemptions and complaint procedures. Acknowledging a request is not necessarily providing the records. RESPONSE / PROCEDURAL CHECK: Indiana APRA distinguishes oral/in-person requests and written requests; written response acknowledgments generally have a seven-day rule. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Indiana Public Access Counselor handbook','https://www.in.gov/dA/36bbfdc7b4/pac-handbook.pdf?language_id=1']]},Iowa:{law:'Iowa Code Chapter 22',summary:'Iowa allows any person to inspect and copy public records subject to confidentiality provisions. The Public Information Board explains permitted request methods, reasonable fees and delays. Iowa Code § 22.15 includes employee-notification rules for certain disciplinary information. RESPONSE / PROCEDURAL CHECK: Iowa generally requires prompt access, without one fixed statutory response period for every request. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Iowa Public Information Board — Chapter 22','https://ipib.iowa.gov/public-records/chapter-22-examination-public-records-open-records'],['Iowa Public Information Board — public records','https://ipib.iowa.gov/public-records']]},Kansas:{law:'Kansas Open Records Act, K.S.A. 45-215 et seq.',summary:'The Kansas Attorney General explains that agencies generally must act on a request by the end of the third business day, which does not always mean records are delivered by then. KORA does not automatically give public employees special access to otherwise closed personnel records. RESPONSE / PROCEDURAL CHECK: Kansas generally requires a response within three business days, not necessarily completion of a complex production. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Kansas Attorney General KORA FAQ','https://www.ag.ks.gov/divisions/administration/open-government/kora-faq'],['Kansas Attorney General resources','https://www.ag.ks.gov/divisions/administration/open-government/resources']]},Kentucky:{law:'Kentucky Open Records Act, KRS 61.870–61.884',summary:'Kentucky Attorney General resources explain state residency qualifications, records requests directed to the custodian of the agency holding the records, and the Attorney General review process for disputes. Confirm current requirements and exceptions before filing. RESPONSE / PROCEDURAL CHECK: Kentucky generally requires a response within five business days; Attorney General review is available under statutory procedures. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Kentucky Attorney General — Open Records and Open Meetings','https://www.ag.ky.gov/Resources/orom/Pages/default.aspx'],['Kentucky Attorney General — request instructions','https://www.ag.ky.gov/Contact-Us/Pages/Open-Records-Requests.aspx']]},Louisiana:{law:'Louisiana Public Records Law, La. R.S. 44:1 et seq.',summary:'Louisiana R.S. 44:31 provides public-record inspection and copying rights, subject to exceptions. R.S. 44:31.1 includes special restrictions for requests involving the governor’s office, including a Louisiana-residency requirement; do not assume identical eligibility for every custodian. RESPONSE / PROCEDURAL CHECK: Louisiana has special three-business-day written-response provisions; access, availability and custodian duties differ. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Louisiana Legislature — R.S. 44:31','https://legis.la.gov/Legis/LawPrint.aspx?d=99688'],['Louisiana Legislature — R.S. 44:31.1','https://www.legis.la.gov/Legis/LawPrint.aspx?d=99689']]},Florida:{law:'Florida Constitution Art. I § 24; Florida Statutes Chapter 119',summary:'Florida provides broad access to public records, subject to statutory and constitutional exemptions. The Attorney General publishes a Government-in-the-Sunshine Manual with Chapter 119 excerpts. Verify the custodian, applicable exemptions and agency procedures before filing. RESPONSE / PROCEDURAL CHECK: Production is required within a reasonable time; there is no universal fixed response deadline. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Florida Attorney General Sunshine Manual','https://www.myfloridalegal.com/sites/default/files/government-in-the-sunshine-manual.pdf']]},Georgia:{law:'Georgia Open Records Act, O.C.G.A. §§ 50-18-70 et seq.',summary:'Georgia’s Attorney General directs requests to the government agency’s records custodian and recommends written requests to document the scope and timing. Agencies need not create nonexistent records, and exemptions may apply. RESPONSE / PROCEDURAL CHECK: Georgia generally requires an initial response within three business days, which is not always the production date. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Georgia Attorney General — how to request','https://law.georgia.gov/key-issues/open-government/how-make-open-records-request'],['Georgia Governor — records overview','https://gov.georgia.gov/contact-us/open-records-request']]},Hawaii:{law:'Uniform Information Practices Act (Modified), Hawaii Revised Statutes Chapter 92F',summary:'Hawaii’s Office of Information Practices administers the UIPA. Chapter 92F addresses general government-record access and separate rights to access or correct certain personal records, subject to exceptions. RESPONSE / PROCEDURAL CHECK: Hawaii UIPA procedures generally use ten business days for an initial response; complex requests and appeals follow administrative rules. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Hawaii Office of Information Practices — UIPA','https://ags.hawaii.gov/oip/uipa-/'],['Hawaii agency — submitting a UIPA request','https://budget.hawaii.gov/contact/uniform-information-practices-act/']]},Idaho:{law:'Idaho Public Records Act, Idaho Code Title 74, Chapter 1',summary:'Idaho Attorney General guidance identifies required contact details and residency declaration for requests to that office. As of July 2024, the guidance describes different response periods for residents and nonresidents; confirm current law and the receiving agency’s procedures. RESPONSE / PROCEDURAL CHECK: Idaho generally requires a grant or denial within three working days, with a ten-working-day period for certain longer responses. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Idaho Attorney General — public records','https://www.ag.idaho.gov/office-resources/public-records/'],['Idaho Attorney General — 2026 manual','https://www.ag.idaho.gov/content/uploads/2026/07/PublicRecordsLaw.pdf']]},Illinois:{law:'Illinois Freedom of Information Act, 5 ILCS 140',summary:'Illinois public-records access is governed by 5 ILCS 140. The Attorney General’s Public Access Counselor handles qualifying requests for review of FOIA denials; section 9.5 generally sets a 60-day review-request period following a final denial, with exceptions and special rules. RESPONSE / PROCEDURAL CHECK: Illinois generally has a five-business-day response period and statutory extensions; review Public Access Counselor appeal procedures. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Illinois Attorney General — Public Access Counselor','https://illinoisattorneygeneral.gov/open-and-honest-government/pac/'],['Illinois General Assembly — FOIA review provision','https://www.ilga.gov/documents/legislation/ilcs/documents/000501400K9.5.htm']]},Arkansas:{law:'Arkansas Freedom of Information Act, Ark. Code Ann. §§ 25-19-101 et seq.',summary:'The Attorney General publishes an updated FOIA handbook. Arkansas law has requester-eligibility rules and exemptions; personnel and employee-evaluation records have special provisions. The Attorney General describes a general three-business-day availability rule, but exceptions and actual request circumstances matter. RESPONSE / PROCEDURAL CHECK: Arkansas has citizenship/residency-related eligibility restrictions; review § 25-19-105 and special rules for active investigations. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Arkansas Attorney General FOIA overview','https://arkansasag.gov/divisions/opinions-foia/arkansas-freedom-of-information-act/'],['Arkansas FOIA handbook (2025)','https://healthy.arkansas.gov/wp-content/uploads/2025-FOIA-Handbook-21st-Edition-ver4.pdf']]},California:{law:'California Public Records Act, Cal. Gov. Code §§ 7920.000–7930.215',summary:'California DOJ explains that requests for state and local agency public records are governed by the California Public Records Act, not federal FOIA. The DOJ describes an initial 10-day determination period with a limited 14-day extension in qualifying circumstances; delivery may take longer. Some personnel and investigative records are exempt. RESPONSE / PROCEDURAL CHECK: Ten calendar days generally applies to an initial determination, not automatic production; a statutory extension may apply. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['California DOJ public records guidance','https://oag.ca.gov/consumers/general/pra'],['California DOJ PRA FAQ','https://oag.ca.gov/consumers/general/pra_faq'],['California DOJ guidelines PDF','https://oag.ca.gov/system/files/media/pra-guidelines.pdf']]},Colorado:{law:'Colorado Open Records Act, C.R.S. §§ 24-72-201–206',summary:'CORA generally covers public records held by Colorado agencies. Colorado has a separate Criminal Justice Records Act, and certain law-enforcement records follow different rules. The Department of Revenue describes a usual three-working-day period, with a possible seven-working-day extension for qualifying circumstances. RESPONSE / PROCEDURAL CHECK: A three-working-day availability standard can be extended under qualifying extenuating circumstances; criminal justice records have separate rules. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Colorado Department of Revenue CORA guidance','https://cdor.colorado.gov/cora'],['Colorado Attorney General CORA and CCJRA','https://coag.gov/media-center/colorado-open-records-act-cora/'],['Colorado legislative CORA summary','https://content.leg.colorado.gov/sites/default/files/colorado-open-records-act-cora-colorado-law-summary-accessible.pdf']]},Connecticut:{law:'Connecticut Freedom of Information Act, Conn. Gen. Stat. §§ 1-200 et seq.',summary:'Connecticut Chapter 14 governs access to public agency records and provides an appeal process through the Freedom of Information Commission. The statute uses a prompt-access standard; users should consult the Commission and current statutes for timing and appeal requirements. RESPONSE / PROCEDURAL CHECK: The FOI Commission generally has a 30-day appeal period after denial; confirm actual and constructive denial rules. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Connecticut General Assembly Chapter 14','https://www.cga.ct.gov/current/pub/chap_014.htm'],['Connecticut 2026 statutory supplement','https://www.cga.ct.gov/2026/sup/chap_014.htm'],['Connecticut Freedom of Information Commission','https://portal.ct.gov/FOI/']]},Delaware:{law:'Delaware Freedom of Information Act, 29 Del. C. §§ 10001–10008',summary:'Delaware maintains an official FOIA portal and state-agency coordinator directory. Its law includes citizenship language, agency submission policies, exemptions and specific routes for challenging denials. A submitted request may itself be a disclosable public record. RESPONSE / PROCEDURAL CHECK: Delaware FOIA generally requires a response within 15 business days, subject to good-faith extension provisions. FEES / EXEMPTIONS: Verify agency-specific copying, search and redaction charges and confidentiality rules, especially public-safety personnel, criminal-investigation and medical records. DENIAL / REVIEW: Preserve the written response and confirm the correct state administrative or court review route and deadline from the current statute before acting. RESEARCH STATUS: Procedural cross-check added; detailed appeal, fee and exception provisions still require source-by-source validation.',links:[['Official Delaware FOIA statute','https://delcode.delaware.gov/title29/c100/index.html'],['Delaware statewide FOIA portal','https://delaware.gov/freedom-of-information-act/'],['Delaware Department of Justice open government','https://attorneygeneral.delaware.gov/executive/open-government/']]},Alaska:{law:'Alaska Statutes §§ 40.25.110–40.25.125',summary:'ELIGIBILITY: Alaska’s Public Records Act covers state and local agencies, but executive-branch regulations do not automatically govern all municipalities, the legislature or courts. SUBMISSION: Make a clear request to the custodian, identifying existing records; electronic-services requests may have separate rules under AS 40.25.115. RESPONSE: For executive-branch requests under AS 40.25.110, 2 AAC 96.325 generally allows an initial 10-working-day response and a 10-working-day extension, with additional extensions possible by agreement or Attorney General approval; response is not always complete production. FEES: Recoverable search and copying charges may require prepayment under 2 AAC 96.360; public-interest fee relief is addressed in 2 AAC 96.370. EXEMPTIONS: Statutory confidential information and protected records are excluded; agencies generally need not create new records. APPEAL: Under 2 AAC 96.340, an executive-branch administrative denial appeal generally must be mailed or hand-delivered to the agency head within 60 working days. AUDIT: Alaska Department of Law APRA guidance and executive-branch regulations reviewed November 18, 2026.',links:[['Alaska Department of Law — APRA guide','https://law.alaska.gov/doclibrary/APRA.html'],['Alaska Legislature — statutes','https://www.akleg.gov/basis/statutes.asp#40.25.110']]},Arizona:{law:'Arizona Revised Statutes §§ 39-121–39-121.03',summary:'ELIGIBILITY: Any person may inspect public records under A.R.S. § 39-121. SUBMISSION: Direct a reasonably specific request to the officer or agency holding the records; noncommercial requests generally need not be written, but document a denial in writing. RESPONSE: Records must be furnished promptly; Arizona has no universal fixed numerical response deadline, and failure to respond promptly may be treated as a denial under § 39-121.01(E). FEES: Inspection and copies differ; reasonable copy fees may apply, and § 39-121.03 imposes additional rules for commercial use. EXEMPTIONS: Confidentiality statutes, privacy, public-safety and other recognized interests may justify withholding; some law-enforcement and victim records have specific protections. REVIEW: § 39-121.02(A) allows a denied requester to seek a special action in superior court without a required administrative appeal; § 39-121.02(B) addresses possible attorney fees and costs for substantially prevailing requesters. AUDIT: Arizona Legislature §§ 39-121–39-121.03 and Ombudsman guidance reviewed November 18, 2026.',links:[['Arizona Legislature — Title 39','https://www.azleg.gov/arsDetail/?title=39'],['Arizona Ombudsman — public records law','https://www.azoca.gov/arizona-public-records-law/'],['Arizona Ombudsman — public records FAQ','https://www.azoca.gov/faqs/faqs-public-access-laws/']]},Alabama:{law:'Alabama Code § 36-12-40 and §§ 36-12-43 through 36-12-45',summary:'ELIGIBILITY: Alabama’s public-records law generally grants access to Alabama residents; an officer may require reasonable proof of residency and may elect to respond to nonresidents. SUBMISSION: Identify records with reasonable specificity; the officer may require its published form or written procedure. RESPONSE: Under § 36-12-44, a proper standard request must be acknowledged within 10 business days and substantively fulfilled or denied within 15 business days after acknowledgment, subject to written 15-business-day extensions and statutory tolling. Time-intensive requests have different fee and 45-business-day procedures. FEES: Reasonable fees and prepayment may be required; inspect the particular agency’s published schedule. EXEMPTIONS: Privileged, confidential and other legally protected records may be withheld; the statute does not require creation of new records. DENIAL/REMEDY: § 36-12-44 establishes conditional presumptions of denial, including 30-business-day/60-calendar-day thresholds for standard requests; court enforcement and applicable limitations should be independently checked before filing. AUDIT: Primary source § 36-12-44 and Alabama Secretary of State procedures reviewed November 18, 2026.',links:[['Official statute § 36-12-40','https://alison.legislature.state.al.us/code-of-alabama?section=36-12-40'],['Official request procedures § 36-12-44','https://alison.legislature.state.al.us/code-of-alabama?section=36-12-44'],['Alabama Secretary of State request instructions','https://www.sos.alabama.gov/public-records-request']]}};
 const verifiedPanel=document.createElement('section');verifiedPanel.className='card';verifiedPanel.id='verified-state';verifiedPanel.setAttribute('aria-label','State public records research and source links');panel.insertBefore(verifiedPanel,draft.previousElementSibling);
 function showVerified(name){verifiedPanel.replaceChildren();const info=verified[name];if(!info){verifiedPanel.hidden=true;return;}verifiedPanel.hidden=false;const title=document.createElement('h3');title.textContent='State public-records law: '+info.law;verifiedPanel.appendChild(title);const p=document.createElement('p');p.textContent=info.summary;verifiedPanel.appendChild(p);for(const [label,url] of info.links){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label;a.style.display='block';a.style.marginBottom='8px';verifiedPanel.appendChild(a);}const disclaimer=document.createElement('p');disclaimer.textContent=enhancedReviewStates.has(name)?'Expanded procedural research, not independently audited for every exception or deadline. Confirm current primary sources before relying on a rule.':'Preliminary research. Fees, exemptions, appeal routes and deadlines still require source-by-source verification. Not attorney-reviewed legal advice.';verifiedPanel.appendChild(disclaimer);const detail=document.createElement('a');detail.href='https://www.rcfp.org/open-government-guide/'+name.toLowerCase().replace(/\\s+/g,'-')+'/';detail.target='_blank';detail.rel='noopener noreferrer';detail.textContent='Read the detailed '+name+' open-records guide (eligibility, exemptions, fees and appeals)';detail.style.display='block';verifiedPanel.appendChild(detail);}

 const slug=name=>name.toLowerCase().replace(/\s+/g,'-');
 const sources='Review the state-specific Reporters Committee guide linked below, then verify current requirements against official statutes and the receiving agency’s instructions.';
 function template(name){return 'PUBLIC RECORDS REQUEST — '+name.toUpperCase()+' (GENERAL STARTING DRAFT; NOT LEGALLY REVIEWED)\n\nDate: [DATE]\nTo: [PUBLIC AGENCY / RECORDS CUSTODIAN]\nAgency address or approved request channel: [ADDRESS / PORTAL]\n\nSubject: Request for access to public records\n\nHello,\n\nI request access to the following identifiable public records maintained by your agency, to the extent disclosure is authorized by applicable '+name+' law:\n\n[DESCRIBE SPECIFIC RECORDS, APPROXIMATE DATES, OFFICES, AND SEARCH TERMS]\n\nPlease let me know whether the records are available electronically and whether any fees apply before processing if the cost will exceed [AMOUNT]. If any responsive material is withheld, please identify the applicable legal basis and provide any reasonably segregable disclosable portions where required by law.\n\nPlease advise me of any agency-specific submission requirements. I understand that requester eligibility, response periods, exemptions, fees and review rights vary and must be independently verified.\n\nThank you,\n[REQUESTER NAME IF REQUIRED]\n[REPLY CONTACT / DELIVERY METHOD]\n\nIMPORTANT: Verify '+name+' requester eligibility, public-records statute, exemptions, response periods and agency rules before sending. Do not request or disclose restricted personnel, criminal justice, medical, privileged or confidential information without authorization.';}
 state.addEventListener('change',()=>{const name=state.value;if(!name){note.textContent='Choose a state to see resource availability.';panel.hidden=true;return;}panel.hidden=false;showVerified(name);if(guideLink){guideLink.href=rcfp+slug(name)+'/';guideLink.textContent=name+' open-government guide (RCFP)';}heading.textContent=name+' — public-records starting resources';intro.textContent=name==='Michigan'?'Michigan: the separate Michigan FOIA Desk offers a locally generated draft. The general template below is also available. '+sources:'Use the resources below to locate '+name+' public-records law, then adapt the free blank request letter. '+sources;note.textContent='Showing '+name+' resources below. Any state summary is preliminary research, not comprehensive legal verification. Check current official sources and deadlines.';draft.textContent=template(name);panel.scrollIntoView({behavior:'smooth',block:'start'});});
 download.addEventListener('click',()=>{if(!state.value)return;const blob=new Blob([draft.textContent],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='the-shield-'+state.value.toLowerCase().replace(/\s+/g,'-')+'-public-records-request.txt';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);});
 print.addEventListener('click',()=>{if(!state.value)return;const w=window.open('','_blank');if(!w){note.textContent='Pop-up blocked. Use the download button and print the saved text file.';return;}const pre=w.document.createElement('pre');pre.style.whiteSpace='pre-wrap';pre.style.fontFamily='serif';pre.style.fontSize='14px';pre.textContent=draft.textContent;w.document.body.appendChild(pre);w.document.title='THE SHIELD — '+state.value+' blank public records request';w.print();});
})();
